diff --git a/instructions/rework/rework_instructions.md b/instructions/rework/rework_instructions.md
index d757f065..9d44d10d 100644
--- a/instructions/rework/rework_instructions.md
+++ b/instructions/rework/rework_instructions.md
@@ -66,6 +66,7 @@ Approved PRs with no unresolved review threads are not rework candidates. If the

 - Do not introduce new logic unrelated to fixing review comments
 - Do not create new branches or push code — this is automated. NEVER push to `main`/`master` (a git guard in your session hard-fails such pushes) and NEVER use closing keywords (`closes/fixes/resolves #N`) in commit messages — the PR body's squash-merge message owns issue closing.
+- NEVER edit the PR body/description (e.g. `gh pr edit --body*`, `gh api …/pulls/N -X PATCH -f body=…`) once the PR carries the `ai_validating` label or is merged/closed — from the moment validation arms the body is FINAL and GitHub never parses closing keywords from a post-merge edit (gh-960, live #956/#952). Post a PR comment instead.
 - Do not change the ticket scope — you are fixing, not re-implementing
 - Do not ignore any BLOCKING or IMPORTANT review comment

diff --git a/js/common/pullRequest.js b/js/common/pullRequest.js
index 84edcbee..637ed691 100644
--- a/js/common/pullRequest.js
+++ b/js/common/pullRequest.js
@@ -169,6 +169,42 @@ function ensureClosesLine(body, ticketKey) {
     return 'Closes #' + num + '\n' + text;
 }

+// gh-960: the PR body (including the canonical 'Closes #N' line) must be final
+// BEFORE the PR enters the merge queue. Live 2026-10-17: PR #956 merged with
+// 'Closes #952' added to the body at the merge moment (finalize-step rewrite
+// after validation armed) — GitHub evaluates closing keywords on creation
+// and body edits, never post-merge, so #952 stayed OPEN. From the moment the
+// validate→merge pipeline arms (ai_validating on the PR) or the PR is
+// merged/closed, a body rewrite is too late and must be skipped.
+var MERGE_QUEUE_BODY_LABELS = ['ai_validating'];
+
+/**
+ * gh-960 rework (review thread js/common/pullRequest.js:192): the label scan
+ * lives in its own helper so isPrBodyFrozen stays under the CI crap gate
+ * (CC ≤ 8) — the loop + name-normalization ternary + indexOf pushed it to 12.
+ * Accepts both GitHub REST label shapes ({name: …} objects) and plain-string
+ * label arrays.
+ */
+function mergeQueueBodyLabelPresent(labels) {
+    labels = labels || [];
+    for (var i = 0; i < labels.length; i++) {
+        var name = labels[i] && labels[i].name !== undefined ? labels[i].name : labels[i];
+        if (MERGE_QUEUE_BODY_LABELS.indexOf(String(name)) !== -1) return true;
+    }
+    return false;
+}
+
+/**
+ * Whether the PR body must be treated as final — the PR entered the merge
+ * queue (validation armed) or is already merged/closed.
+ */
+function isPrBodyFrozen(pr) {
+    if (!pr || typeof pr !== 'object') return false;
+    if (pr.merged === true) return true;
+    var state = String(pr.state || '').toLowerCase();
+    return state === 'closed' || state === 'merged' || mergeQueueBodyLabelPresent(pr.labels);
+}
+
 // GitHub limits PR bodies to 65536 characters. Keep a safety margin so
 // gh pr create does not fail on oversized bodies generated by agents.
 var MAX_GH_PR_BODY_LENGTH = 60000;
@@ -688,6 +724,7 @@ module.exports = {
     sanitizeCommitMessage: sanitizeCommitMessage,
     extractIssueNumber: extractIssueNumber,
     ensureClosesLine: ensureClosesLine,
+    isPrBodyFrozen: isPrBodyFrozen,
     buildOriginFetchCommand: buildOriginFetchCommand,
     buildTargetedOriginFetchCommand: buildTargetedOriginFetchCommand,
     ensureRemoteBranchRef: ensureRemoteBranchRef,
diff --git a/js/common/scm.js b/js/common/scm.js
index 9521361d..befcfd0b 100644
--- a/js/common/scm.js
+++ b/js/common/scm.js
@@ -476,6 +476,39 @@ function _githubGetRemoteRepoInfo() {
     } catch (e) { return null; }
 }

+/**
+ * gh-960: machine-owned PR body rewrite via `gh api …/pulls/{id} -X PATCH`.
+ * Review thread js/postTestReworkResults.js:214 pinned that the previous
+ * updatePrBody seam was dead — no provider implemented it, so the rework-publish
+ * freeze + ensureClosesLine wrapping never executed outside mock-SCM tests.
+ * The body travels through a temp file because `gh api -F key=@file` sends the
+ * file's exact contents — no shell quoting/escaping can mangle a multi-line
+ * Markdown body that way. Returns the gh output, or null when the call failed
+ * (threw or returned nothing — gh prints the updated PR JSON on success).
+ */
+function _githubUpdatePrBody(workspace, repository, prId, body) {
+    var prIdStr = String(prId);
+    var tempBodyPath = 'pr_body_update_tmp_' + prIdStr + '.md';
+    try {
+        file_write(tempBodyPath, body === null || body === undefined ? '' : String(body));
+        var raw = cli_execute_command({
+            command: 'gh api repos/' + workspace + '/' + repository + '/pulls/' + prIdStr +
+                ' -X PATCH -F body=@' + tempBodyPath
+        });
+        var cleaned = _cleanCommandOutput(raw || '');
+        if (!cleaned) {
+            console.warn('SCM GitHub: updatePrBody for PR ' + prIdStr + ' returned no output — treating as failed');
+            return null;
+        }
+        return cleaned;
+    } catch (e) {
+        console.warn('SCM GitHub: updatePrBody for PR ' + prIdStr + ' failed:', e.message || e);
+        return null;
+    } finally {
+        try { file_delete({ path: tempBodyPath }); } catch (e) { /* best-effort cleanup */ }
+    }
+}
+
 function _createGithubProvider(workspace, repository) {
     return {
         listPrs: function(state) {
@@ -558,6 +591,13 @@ function _createGithubProvider(workspace, repository) {
                 command: 'gh api repos/' + (owner || workspace) + '/' + (repo || repository) + '/pulls/' + prId + '/update-branch -X PUT'
             });
         },
+        // gh-960: machine-owned body rewrite (was a dead seam — see
+        // _githubUpdatePrBody). Callers must gate on isPrBodyFrozen() before
+        // invoking: once validation is armed / the PR is merged, the body is
+        // final and must not be rewritten.
+        updatePrBody: function(prId, body) {
